    ): Flow<D, A, Out & Named<N, { readonly rounds: number; readonly satisfied: boolean; readonly last: O2 }>, Seats | S, Marks | M>;
    spawn<N extends string, CD>(
      name: N,
      lane: LaneRef<CD>,
      children: (ctx: Ctx<D, A, Out>) => readonly Supply<CD>[],
