    maxUsd(usd: number, options?: { readonly onExceed: 'halt' | 'fail' }): Lane<D, St, Seats, Marks>;
    deadline(at: (unit: UnitView<D>) => Date): Lane<D, St, Seats, Marks>;
  }

  export interface Journal {
